# Cleaner approach: for each row with zeros, fill them based on the pattern that already exists in the row

base2 = [2, 3, 4, 5, 6, 7, 8, 9, 1]  # Used by row 0, and rows 4-8, etc.
base1 = [3, 4, 5, 6, 7, 8, 9, 1, 2]  # Used by rows 1-3, 17-22

def fill_row(row, use_pattern):
    """Fill zeros using the given pattern, continuing from the first non-zero position"""
    result = row[:]
    pattern = use_pattern

    # Find the first non-zero column
    first_nonzero = next((c for c in range(23) if result[c] != 0), -1)

    if first_nonzero >= 0:
        # Use the value at first_nonzero to determine where pattern[0] is
        # Then fill backward
        for c in range(23):
            if result[c] == 0:
                # Find pattern index: if first_nonzero has pattern[0], then c has pattern[(first_nonzero - c)%9]
                idx = (first_nonzero - c) % 9
                result[c] = pattern[idx]
    else:
        # No non-zero, just use pattern repeating from 0
        for c in range(23):
            result[c] = pattern[c % 9]

    return result

# Generate output grid
output = []

for r in range(23):
    row = grid[r]

    if r == 0:
        # Row 0 uses base2 pattern
        filled = fill_row(row, base2)
    else:
        # Other rows: need to figure out which pattern
        # Let me check by looking at the "after zeros" sequence

        # Find first non-zero
        for c in range(23):
            if row[c] != 0:
                first_nonzero = c
                start_val = row[c]
                break
        else:
            first_nonzero = 0
            start_val = "N/A"

        # Find where in base1 or base2 the start_val appears
        if start_val in base2:
            use_pattern = base2
        else:
            use_pattern = base1

        filled = fill_row(row, use_pattern)
        output.append(filled)

print("\n=== OUTPUT GRID ===")
for r in range(23):
    if r < 6 or r >= 20:
        print(f"Row {r}: {output[r]}")
    elif r == 6:
        print(f"Row {r} (checking): {output[r]}")

# Verify against input
print("\nVerification:")
for r in range(23):
    if r == 0:
        continue
    # Check that filled matches input where input has non-zero
    match = True
    for c in range(23):
        if grid[r][c] != 0 and grid[r][c] != output[r][c]:
            print(f"Row {r}, col {c}: input {grid[r][c]}, output {output[r][c]}")
            match = False
    if match:
        print(f"Row {r}: OK")

# Submit final answer
import json
